"use client";

import React, { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase';
import { useRouter } from 'next/navigation';
import { UploadCloud, ArrowLeft, Image as ImageIcon, Plus, Trash2, Loader2, X } from 'lucide-react';

interface Category {
  id: string;
  name: string;
  status?: any;
}

interface VariantInput {
  unit: string;
  price: string;
  stock: string;
}

const ALLOWED_TYPES = ['image/jpeg', 'image/png', 'image/webp'];
const MAX_IMAGE_MB = 5;

// Same "off" values the Categories page understands
const OFF_WORDS = ['inactive', 'disabled', 'disable', 'hidden', 'draft', 'archived', 'off', 'false', '0'];
const categoryEnabled = (c: Category) => {
  const v = c.status;
  if (v === false || v === 0) return false;
  if (typeof v === 'string') return !OFF_WORDS.includes(v.trim().toLowerCase());
  return true;
};

const validateImage = (file: File): string | null => {
  if (!ALLOWED_TYPES.includes(file.type)) return 'Use a JPG, PNG or WebP image.';
  if (file.size > MAX_IMAGE_MB * 1024 * 1024) return `Image must be under ${MAX_IMAGE_MB} MB.`;
  return null;
};

// Client-side resize + WebP conversion
const compressAndConvertToWebP = (file: File, maxWidth = 1000, quality = 0.82): Promise<File> =>
  new Promise((resolve) => {
    if (!file.type.startsWith('image/')) return resolve(file);
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let { width, height } = img;
        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }
        canvas.width = width;
        canvas.height = height;
        canvas.getContext('2d')?.drawImage(img, 0, 0, width, height);
        canvas.toBlob(
          (blob) => {
            if (!blob) return resolve(file);
            const clean = file.name.substring(0, file.name.lastIndexOf('.')) || 'product';
            resolve(new File([blob], `${clean}_${Date.now()}.webp`, { type: 'image/webp' }));
          },
          'image/webp',
          quality
        );
      };
      img.onerror = () => resolve(file);
    };
    reader.onerror = () => resolve(file);
  });

const inputCls =
  'w-full min-h-11 sm:min-h-9 py-2 px-3 text-base sm:text-[13px] text-[#1a1a1a] placeholder:text-[#8a8a8a] bg-white rounded-lg shadow-[0_0_0_1px_rgba(0,0,0,0.2)] outline-none focus:shadow-[0_0_0_2px_#005bd3] transition-shadow';

export default function AddProductPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [compressing, setCompressing] = useState(false);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [dbCategories, setDbCategories] = useState<Category[]>([]);
  const [error, setError] = useState('');
  const [imageError, setImageError] = useState('');

  const [product, setProduct] = useState({ name: '', category: '', description: '' });

  const [variants, setVariants] = useState<VariantInput[]>([
    { unit: '500g', price: '250', stock: '20' },
    { unit: '1 kg', price: '480', stock: '30' },
  ]);

  useEffect(() => {
    const fetchCats = async () => {
      const { data } = await supabase.from('categories').select('*').order('name');
      if (data) {
        // only enabled categories can receive new products
        const enabled = (data as Category[]).filter(categoryEnabled);
        setDbCategories(enabled);
        if (enabled.length > 0) setProduct((prev) => ({ ...prev, category: enabled[0].name }));
      }
    };
    fetchCats();
  }, []);

  useEffect(() => {
    return () => {
      if (imagePreview) URL.revokeObjectURL(imagePreview);
    };
  }, [imagePreview]);

  const handleImageSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file) return;

    const err = validateImage(file);
    if (err) {
      setImageError(err);
      return;
    }
    setImageError('');
    setCompressing(true);
    try {
      const webp = await compressAndConvertToWebP(file);
      setImageFile(webp);
      setImagePreview(URL.createObjectURL(webp));
    } catch (err) {
      console.error('Image compression error:', err);
      setImageFile(file);
      setImagePreview(URL.createObjectURL(file));
    } finally {
      setCompressing(false);
    }
  };

  const removeImage = () => {
    setImageFile(null);
    setImagePreview(null);
  };

  const addVariantField = () => setVariants([...variants, { unit: '', price: '', stock: '0' }]);
  const removeVariantField = (index: number) => setVariants(variants.filter((_, i) => i !== index));
  const updateVariantField = (index: number, field: keyof VariantInput, value: string) => {
    const updated = [...variants];
    updated[index] = { ...updated[index], [field]: value };
    setVariants(updated);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!product.name.trim()) return setError('Product name is required.');
    if (!product.category) return setError('Please select a category.');
    if (!imageFile) {
      setImageError('A product image is required.');
      return setError('Please add a product image.');
    }
    if (variants.length === 0) return setError('At least one variant is required.');

    const parsed = [];
    for (let i = 0; i < variants.length; i++) {
      const v = variants[i];
      const price = Number(v.price);
      const stock = Number(v.stock);
      if (!v.unit.trim()) return setError(`Variant ${i + 1}: enter a unit, for example 500g.`);
      if (v.price.trim() === '' || !isFinite(price) || price < 0) return setError(`Variant ${i + 1}: enter a valid price.`);
      if (v.stock.trim() === '' || !Number.isInteger(stock) || stock < 0) return setError(`Variant ${i + 1}: stock must be a whole number, 0 or more.`);
      parsed.push({ unit: v.unit.trim(), price, stock });
    }

    setLoading(true);
    try {
      const fileName = `${Date.now()}_${Math.random().toString(36).substring(2)}.webp`;
      const { error: uploadError } = await supabase.storage.from('products').upload(fileName, imageFile, { contentType: 'image/webp' });
      if (uploadError) throw uploadError;
      const downloadURL = supabase.storage.from('products').getPublicUrl(fileName).data.publicUrl;

      const matchedCat = dbCategories.find((c) => c.name === product.category);

      const { data: newProd, error: insertError } = await supabase
        .from('products')
        .insert({
          name: product.name.trim(),
          category_id: matchedCat?.id || null,
          category_name: product.category,
          description: product.description,
          image_url: downloadURL,
          is_available: true,
        })
        .select()
        .single();
      if (insertError) throw insertError;

      const variantRows = parsed.map((v) => ({
        product_id: newProd.id,
        unit: v.unit,
        price: v.price,
        stock: v.stock,
        sku: `${product.name.trim().toUpperCase().substring(0, 4)}-${v.unit.toUpperCase()}`,
        is_available: v.stock > 0,
      }));

      const { error: varError } = await supabase.from('product_variants').insert(variantRows);
      if (varError) {
        // don't leave a product with no variants behind
        await supabase.from('products').delete().eq('id', newProd.id);
        throw varError;
      }

      router.push('/products');
    } catch (err: any) {
      console.error('Upload error:', err);
      setError(err?.message || 'Failed to create product');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto space-y-5">
      <div className="flex items-center gap-3">
        <button
          type="button"
          onClick={() => router.push('/products')}
          className="p-2 -ml-2 rounded-lg text-[#616161] hover:bg-black/5"
          aria-label="Back to products"
        >
          <ArrowLeft size={18} />
        </button>
        <h1 className="text-xl font-semibold text-[#1a1a1a]">Add product</h1>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {error && (
          <p role="alert" className="rounded-lg bg-[#fed1d7] px-3 py-2 text-sm sm:text-[13px] text-[#8e0b21]">
            {error}
          </p>
        )}

        {/* GENERAL */}
        <Card className="p-4 sm:p-5 space-y-4">
          <h2 className="text-sm font-semibold text-[#1a1a1a]">Product details</h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Field label="Product name">
              <input
                type="text"
                placeholder="e.g. Padma Hilsa (Ilish) Whole"
                value={product.name}
                onChange={(e) => setProduct({ ...product, name: e.target.value })}
                className={inputCls}
              />
            </Field>

            <Field label="Category">
              <select
                value={product.category}
                onChange={(e) => setProduct({ ...product, category: e.target.value })}
                className={`${inputCls} cursor-pointer`}
              >
                {dbCategories.length === 0 && <option value="">No active categories</option>}
                {dbCategories.map((cat) => (
                  <option key={cat.id} value={cat.name}>{cat.name}</option>
                ))}
              </select>
            </Field>
          </div>

          <Field label="Description">
            <textarea
              rows={3}
              placeholder="Fresh catch details, origin, culinary notes…"
              value={product.description}
              onChange={(e) => setProduct({ ...product, description: e.target.value })}
              className={inputCls}
            />
          </Field>
        </Card>

        {/* IMAGE */}
        <Card className="p-4 sm:p-5 space-y-4">
          <h2 className="text-sm font-semibold text-[#1a1a1a]">
            Image <span className="text-[#8e0b21]">*</span>
          </h2>

          <div className="flex items-center gap-4">
            <div
              className={`h-28 w-28 bg-[#f7f7f7] rounded-lg overflow-hidden flex items-center justify-center shrink-0 relative ${
                imageError ? 'shadow-[0_0_0_1px_#e22c38]' : 'shadow-[0_0_0_1px_rgba(0,0,0,0.12)]'
              }`}
            >
              {compressing ? (
                <div className="text-center space-y-1 p-2">
                  <Loader2 size={20} className="animate-spin text-[#616161] mx-auto" />
                  <span className="text-xs text-[#616161] block">Optimizing…</span>
                </div>
              ) : imagePreview ? (
                <>
                  <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                  <button
                    type="button"
                    onClick={removeImage}
                    className="absolute top-1 right-1 p-1 rounded-full bg-black/60 text-white hover:bg-black/80"
                    aria-label="Remove image"
                  >
                    <X size={12} />
                  </button>
                </>
              ) : (
                <ImageIcon className="text-[#8a8a8a]" size={30} />
              )}
            </div>

            <div className="space-y-2 flex-1 min-w-0">
              <label className="cursor-pointer min-h-11 sm:min-h-9 py-2 px-3 inline-flex items-center gap-2 rounded-lg bg-white text-sm sm:text-[13px] font-medium text-[#303030] shadow-[0_0_0_1px_rgba(0,0,0,0.12)] hover:bg-gray-50">
                <UploadCloud size={15} /> {imageFile ? 'Change image' : 'Select image'}
                <input type="file" accept="image/jpeg,image/png,image/webp" onChange={handleImageSelect} className="hidden" />
              </label>
              <p className={`text-xs leading-snug ${imageError ? 'text-[#8e0b21]' : 'text-[#616161]'}`}>
                {imageError || `Required · JPG, PNG or WebP · max ${MAX_IMAGE_MB} MB. It is resized and converted to WebP automatically.`}
              </p>
            </div>
          </div>
        </Card>

        {/* VARIANTS */}
        <Card className="p-4 sm:p-5 space-y-4">
          <div className="flex justify-between items-start gap-3">
            <div>
              <h2 className="text-sm font-semibold text-[#1a1a1a]">Variants</h2>
              <p className="text-xs text-[#616161] mt-0.5">Options like 250g, 500g or 1 kg, each with its own price and stock.</p>
            </div>
            <button
              type="button"
              onClick={addVariantField}
              className="min-h-9 py-1.5 px-3 shrink-0 inline-flex items-center gap-1.5 rounded-lg bg-white text-sm sm:text-[13px] font-medium text-[#303030] shadow-[0_0_0_1px_rgba(0,0,0,0.12)] hover:bg-gray-50"
            >
              <Plus size={14} /> Add variant
            </button>
          </div>

          <div className="space-y-3">
            {variants.map((v, idx) => (
              <div key={idx} className="bg-[#f7f7f7] rounded-lg p-3 grid grid-cols-2 sm:grid-cols-[1fr_130px_110px_auto] gap-3 items-end">
                <div className="col-span-2 sm:col-span-1">
                  <Field label="Unit">
                    <input
                      type="text"
                      placeholder="e.g. 500g / 1 kg"
                      value={v.unit}
                      onChange={(e) => updateVariantField(idx, 'unit', e.target.value)}
                      className={inputCls}
                    />
                  </Field>
                </div>

                <Field label="Price (₹)">
                  <input inputMode="decimal" value={v.price} onChange={(e) => updateVariantField(idx, 'price', e.target.value)} className={inputCls} />
                </Field>

                <Field label="Stock">
                  <input inputMode="numeric" value={v.stock} onChange={(e) => updateVariantField(idx, 'stock', e.target.value)} className={inputCls} />
                </Field>

                {variants.length > 1 ? (
                  <button
                    type="button"
                    onClick={() => removeVariantField(idx)}
                    className="col-span-2 sm:col-span-1 min-h-11 sm:min-h-9 px-3 rounded-lg text-[#8a8a8a] hover:text-[#8e0b21] hover:bg-[#fed1d7]/50 inline-flex items-center justify-center gap-1.5 text-sm sm:text-[13px]"
                    aria-label={`Remove variant ${idx + 1}`}
                  >
                    <Trash2 size={15} /> <span className="sm:hidden">Remove</span>
                  </button>
                ) : (
                  <span className="hidden sm:block" />
                )}
              </div>
            ))}
          </div>
        </Card>

        {/* SUBMIT */}
        <div className="flex gap-2 justify-end">
          <button
            type="button"
            onClick={() => router.push('/products')}
            disabled={loading}
            className="min-h-11 sm:min-h-10 px-4 rounded-lg bg-white text-sm sm:text-[13px] font-medium text-[#303030] shadow-[0_0_0_1px_rgba(0,0,0,0.12)] hover:bg-gray-50 disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={loading || compressing}
            className="flex-1 sm:flex-none sm:min-w-[160px] min-h-11 sm:min-h-10 px-5 rounded-lg bg-[#303030] hover:bg-[#1a1a1a] text-sm sm:text-[13px] font-medium text-white disabled:opacity-50 inline-flex items-center justify-center gap-2 transition-colors"
          >
            {loading ? <Loader2 size={16} className="animate-spin" /> : 'Save product'}
          </button>
        </div>
      </form>
    </div>
  );
}

function Card({ children, className = '' }: { children: React.ReactNode; className?: string }) {
  return <div className={`bg-white rounded-xl shadow-[0_0_0_1px_rgba(0,0,0,0.06),0_1px_2px_rgba(0,0,0,0.04)] ${className}`}>{children}</div>;
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <label className="block space-y-1.5">
      <span className="text-sm sm:text-[13px] font-medium text-[#303030]">{label}</span>
      {children}
    </label>
  );
}